"""Draft eight primary-bound Hail roles, distinguishing Batch, QC, liftover and reused MatrixTable statistics. Does not apply catalog changes."""
import argparse,gzip,hashlib,json,re,xml.etree.ElementTree as ET
from pathlib import Path
from setup_deseq2_reference import ROOT,pin,save
from collect_omics_review import paragraphs,validate_supporting_evidence
from biomart_catalog import load_catalog_registry

ROLES={
'P055':(64,None,'cloud-workflow-orchestration','Used Hail Batch with GNU Parallel for large-scale cloud parallelization of the modified RCTD cell-type mapping workflow, reaching thousands of cores.','This is Hail Batch/hailtop orchestration, not execution of Hail genotype QC or association. The paper does not report a Hail release, immutable batch DAG, cloud/backend configuration or billing/resource settings. OSQP and Rcpp changes belong to RCTD itself. Local Batch controls do not establish the paper cloud scale or RCTD model parity.'),
'P168':(41,None,'joint-genotyping-pipeline-framework','Used HAIL alongside GATK GenotypeGVCFs in the Broad Joint Genotyping pipeline for the WES callset before downstream ancestry and sample/genotype/variant quality control.','The Hail release, exact Hail API calls and immutable pipeline revision are not specified here. BWA-MEM alignment, GATK single-sample calling and the jointly described GATK genotyping steps are not reattributed to Hail algorithms. The neighboring QC thresholds and random-forest rules remain study-specific; no unreported Hail mask or operation order is inferred.'),
'P186':(9,'0.2','reference-panel-genotype-sample-variant-QC','Applied iterative genotype-, sample- and variant-level QC using Hail v0.2 to the whole-genome sequences used to construct the SISu v4.2 reference panel, before Eagle phasing and Beagle-based imputation.','The exact Hail patch release, successive masks and iteration criteria are unspecified. The Hail statement concerns reference-panel WGS QC; the nearby array-QC thresholds and post-imputation INFO filter are not automatically reassigned to this Hail stage. REGENIE performed the described FinnGen GWAS; Hail is not credited as that association fitter.'),
'P191':(14,'0.2.130','risk-variant-coordinate-liftover','Lifted the supplied eMERGE risk variants from GRCh37 to GRCh38 using Hail0.2.130 before calculating raw polygenic scores with the separate AoUPRS library.','The source does not specify a chain-file identity, min_match, interval convention, reverse-strand allele handling or unmapped policy. These must be explicit in a supplied workflow. AoUPRS score calculation and subsequent PC-dependent mean/variance calibration are separate operations; this Hail use does not establish genotype QC, GWAS fitting or calibrated PGS inference.'),
'P204':(34,'0.2.116','WES-preprocessing-sample-QC-and-LD-MAF','Used Hail0.2.116 for UKB WES preprocessing and QC, including the LD-pruned high-confidence sample-QC set and QC metrics residualized on20 genotype PCs. Hail with Python also calculated per-gene LD matrices and per-variant MAFs reused by COAST-SS.','The site-QC rules, sample/covariate exclusions,20-PC residualization and six-MAD filtering are study choices, not inferred library defaults. The later LD/MAF paragraph does not separately pin its Hail release. VEP/LOFTEE annotation, per-variant association fitting and COAST/COAST-SS allelic-series tests remain distinct software stages; a generic QC or LD export is not a reproduction of the complete study mask.'),
'P210':(13,None,'ES-WGS-preprocessing-framework-description','Reports ES/WGS processing using GATK or Hail; the outlined pipeline separately names BWA-MEM alignment, Picard duplicate marking and GATK recalibration, gVCF calling, joint genotyping and VQSR.','The paragraph does not identify a Hail release, exact Hail operations or which cohort used the Hail branch. Do not attribute BWA/Picard/GATK algorithms or every later empirical QC threshold to Hail, infer a framework-specific joint-calling implementation, or manufacture the unreported branch configuration.'),
'P220':(12,None,'sample-QC-with-stratified-MAD-and-reused-MatrixTable','Ran Hail sample_qc() for UKB exome sample QC, applying median-plus-or-minus-four-MAD exclusions within ancestry super-populations and separately by ES tranche. Separately obtained previously calculated Genebass gene-association summaries in Hail MatrixTable format.','The associated XML list identifies deletion/insertion/SNP counts and three count-ratio metrics. The Hail release, precise MAD scaling and complete code/order are not pinned. Neighboring genotype/site masks and VEP/LOFTEE annotation remain separate. The Genebass MatrixTable is a reused summary-statistic resource; its download does not establish that this paper recomputed the Genebass SKAT-O tests using Hail.'),
'P246':(6,'0.2.78','MANE-transcript-restricted-CASR-variant-QC','Performed QC with HAIL0.2.78 and PLINK2 on the UKB CASR variants restricted to the named MANE transcript ENST00000639785.2/RefSeq NM_000388.4 before downstream locus/phenotype analyses.','The primary paragraph does not give the complete Hail mask, per-tool division of the QC steps or exact Hail functions; supplemental parameters are not invented. The MANE transcript identity must not be silently updated. Fisher/Firth tests, subsequent variant scoring and ancestry-stratified meta-analysis are separate methods, not inferred Hail association operations.')}

def pointer(p):return dict(paragraph_index=p['paragraph_index'],section=p['section'],paragraph_sha256=hashlib.sha256(p['text'].encode('utf8')).hexdigest())
def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--out',required=True,type=Path);a=p.parse_args();out=a.out.resolve();assert not out.exists();out.mkdir(parents=True);data=ROOT/'docs/literature/omics-2023-2026';before={p.relative_to(ROOT).as_posix():pin(p) for p in [data/'papers.json',data/'tool-inventory.json',data/'summary.json',ROOT/'tools/literature/reviewed-uses.json']};papers=json.loads((data/'papers.json').read_bytes());registry={r['id']:r for r in load_catalog_registry(ROOT)};drafts=[]
    for paper in papers:
        if paper['paper_id'] not in ROLES:continue
        id=paper['paper_id'];index,version,context,summary,note=ROLES[id];raw=gzip.decompress((ROOT/'build/literature-review/xml'/(paper['pmcid']+'.xml.gz')).read_bytes());assert hashlib.sha256(raw).hexdigest()==paper['xml_sha256'];root=ET.fromstring(raw);assert next(e.text for e in root.findall('front/article-meta/article-id') if e.get('pub-id-type')=='doi').lower()==paper['doi'].lower();ps=paragraphs(root);by={p['paragraph_index']:p for p in ps};anchor=by[index];assert re.search(registry['hail']['pattern'],anchor['match_text'],re.I);old=next(t for t in paper['tools'] if t['tool_id']=='hail');assert old['review_status']=='source-evidence-extracted; semantic-completeness-review-open';review=dict(pmcid=paper['pmcid'],doi=paper['doi'],tool_id='hail',evidence_paragraph_sha256=hashlib.sha256(anchor['text'].encode('utf8')).hexdigest(),use_summary=summary,implementation_scope_note=note,version_reported_near_name=version,usage_context=context)
        if id=='P204':
            detail=pointer(by[33]);detail.update(evidence_role='method-details',named_anchor=pointer(anchor),shared_terms=['call rate'],relation_note='The immediately preceding UKB site-QC paragraph supplies the variant filters for the high-confidence QC set in the named Hail preprocessing paragraph; annotation tools and downstream tests remain distinguished.');review['supporting_evidence']=[detail,pointer(by[45])]
        if id=='P220':review['supporting_evidence']=[pointer(by[37])]
        validate_supporting_evidence(ps,[review],registry);drafts.append(dict(paper_id=id,primary_paragraph=index,section=anchor['section'],review=review,xml_sha256=paper['xml_sha256']))
    assert [d['paper_id'] for d in drafts]==list(ROLES) and len(drafts)==8;save(out/'hail-use-review-drafts.json',drafts);assert all(pin(ROOT/n)==v for n,v in before.items());save(out/'COMPLETED.json',dict(status='PASS_EIGHT_PRIMARY_BOUND_HAIL_ROLE_DRAFTS_NOT_APPLIED',new_review_drafts=8,supporting_pointers=3,prior_reviews_unchanged=952,papers_or_catalog_modified=False,source_pins={Path(__file__).resolve().relative_to(ROOT).as_posix():pin(Path(__file__))},catalog_before_and_after=before,whole_goal_complete=False));print('Drafted8 source-bound Hail roles and3 supporting pointers; existing952 reviews and catalog unchanged')

if __name__=='__main__':
    if not __debug__:raise RuntimeError('Never disable exact primary-source/draft checks')
    main()
